/// <summary>Exercises real account persistence through authenticated Cowork routes across host recreation.</summary>
[Trait("Category", "Live")]
public sealed class CoworkPersistenceTests : IAsyncLifetime
{
    private readonly string _schema = "t_" + Guid.NewGuid().ToString("n");
    private readonly string _role = "r_" + Guid.NewGuid().ToString("n");
    private readonly string _password = Guid.NewGuid().ToString("n") + Guid.NewGuid().ToString("n");
    private NpgsqlDataSource? _admin;
    private NpgsqlDataSource? _app;
    private NpgsqlDataSource? _otherApp;

    public async ValueTask InitializeAsync()
    {
        var connection = Environment.GetEnvironmentVariable("AUTONOGRAMMER_TEST_POSTGRES_CONNECTION");
        if (string.IsNullOrWhiteSpace(connection)) throw new InvalidOperationException("A run-owned test PostgreSQL connection is required.");
        _admin = NpgsqlDataSource.Create(connection);
        await new MigrationRunner(_admin, _schema).MigrateAsync(CancellationToken.None).ConfigureAwait(true);
        var grants = _admin.CreateCommand($"""
            CREATE ROLE "{_role}" LOGIN PASSWORD '{_password}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
            GRANT USAGE ON SCHEMA "{_schema}" TO "{_role}";
            GRANT SELECT, INSERT, UPDATE, DELETE ON "{_schema}".cowork_projects, "{_schema}".cowork_instructions,
                "{_schema}".cowork_memory_entries, "{_schema}".cowork_memory_settings, "{_schema}".cowork_memory_idempotency,
                "{_schema}".account_lifecycle TO "{_role}";
            """);
        await using (grants.ConfigureAwait(true))
        {
            await grants.ExecuteNonQueryAsync(CancellationToken.None).ConfigureAwait(true);
        }
        var appConnection = new NpgsqlConnectionStringBuilder(connection)
        {
            SearchPath = _schema + ",public",
            ApplicationName = _schema,
            Username = _role,
            Password = _password,
        }.ConnectionString;
        _app = NpgsqlDataSource.Create(appConnection);
        _otherApp = NpgsqlDataSource.Create(appConnection);
        await AssertAppRoleAsync(_app).ConfigureAwait(true);
        await AssertAppRoleAsync(_otherApp).ConfigureAwait(true);
        await AccountLifecycleProvisioning.ProvisionAsync(_app, ["alice", "bob"], CancellationToken.None).ConfigureAwait(true);
    }

    private static async Task AssertAppRoleAsync(NpgsqlDataSource source)
    {
        var check = source.CreateCommand("""
            SELECT NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole
                AND NOT has_schema_privilege(current_user, current_schema(), 'CREATE')
                AND NOT has_table_privilege(current_user, 'cowork_projects', 'TRUNCATE')
            FROM pg_roles WHERE rolname = current_user
            """);
        await using var checkAsyncDisposal = check.ConfigureAwait(true);
        ((bool)(await check.ExecuteScalarAsync(CancellationToken.None).ConfigureAwait(true))!).ShouldBeTrue();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null) await _app.DisposeAsync().ConfigureAwait(true);
        if (_otherApp is not null) await _otherApp.DisposeAsync().ConfigureAwait(true);
        if (_admin is null) return;
        var command = _admin.CreateCommand("DROP SCHEMA IF EXISTS " + _schema + " CASCADE; DROP ROLE IF EXISTS " + _role);
        await using var commandAsyncDisposal = command.ConfigureAwait(true);
        await command.ExecuteNonQueryAsync(CancellationToken.None).ConfigureAwait(true);
        await _admin.DisposeAsync().ConfigureAwait(true);
    }

    [Fact]
    public async Task RestartPreservesOnlyOwnedProjectsInstructionsAndMemory()
    {
        var token = TestContext.Current.CancellationToken;
        {
            var host = await StartAsync().ConfigureAwait(true);
            await using var hostAsyncDisposal = host.ConfigureAwait(true);
            using var alice = Client(host, "alice");
            using var bob = Client(host, "bob");
            await SeedAndCheckRefusalsAsync(alice, bob, token).ConfigureAwait(true);
        }

        {
            var host = await StartAsync().ConfigureAwait(true);
            await using var hostAsyncDisposal = host.ConfigureAwait(true);
            using var alice = Client(host, "alice");
            using var bob = Client(host, "bob");
            await CheckRestartAndCascadeAsync(alice, bob, token).ConfigureAwait(true);
        }
    }

    private static async Task SeedAndCheckRefusalsAsync(HttpClient alice, HttpClient bob, CancellationToken token)
    {
        using var createdBody = Json("{\"id\":\"p1\",\"name\":\"Alpha\",\"description\":\"persisted\"}");
        using var created = await alice.PutAsync(Route("/cowork/projects/p1"), createdBody, token).ConfigureAwait(true);
        created.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var otherBody = Json("{\"id\":\"p2\",\"name\":\"Beta\"}");
        using var other = await bob.PutAsync(Route("/cowork/projects/p2"), otherBody, token).ConfigureAwait(true);
        other.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var folderBody = Json("{\"id\":\"folder\",\"name\":\"No\",\"folders\":[\"/tmp/private\"]}");
        using var folder = await alice.PutAsync(Route("/cowork/projects/folder"), folderBody, token).ConfigureAwait(true);
        folder.StatusCode.ShouldBe(HttpStatusCode.BadRequest);
        using var instructionsBody = Json("{\"instructions\":\"remember this\"}");
        using var instructions = await alice.PutAsync(Route("/cowork/instructions/global"), instructionsBody, token).ConfigureAwait(true);
        using var foreignUpdateBody = Json("{\"id\":\"p1\",\"name\":\"stolen\"}");
        using var foreignUpdate = await bob.PutAsync(Route("/cowork/projects/p1"), foreignUpdateBody, token).ConfigureAwait(true);
        foreignUpdate.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        instructions.StatusCode.ShouldBe(HttpStatusCode.OK);
        using var settingsBody = Json("{\"enabled\":true,\"paused\":false,\"includeSensitive\":false}");
        using var settings = await alice.PutAsync(Route("/cowork/memory/settings"), settingsBody, token).ConfigureAwait(true);
        settings.StatusCode.ShouldBe(HttpStatusCode.OK);
        using var projectMemoryBody = Json("{\"projectId\":\"p1\",\"content\":\"project note\"}");
        using var projectMemory = await alice.PostAsync(Route("/cowork/memory"), projectMemoryBody, token).ConfigureAwait(true);
        projectMemory.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var accountMemoryBody = Json("{\"content\":\"account note\"}");
        using var accountMemory = await alice.PostAsync(Route("/cowork/memory"), accountMemoryBody, token).ConfigureAwait(true);
        accountMemory.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var bobMemoryBody = Json("{\"projectId\":\"p2\",\"content\":\"bob note\"}");
        using var bobMemory = await bob.PostAsync(Route("/cowork/memory"), bobMemoryBody, token).ConfigureAwait(true);
        bobMemory.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var foreignBody = Json("{\"projectId\":\"p2\",\"content\":\"rejected\"}");
        using var foreign = await alice.PostAsync(Route("/cowork/memory"), foreignBody, token).ConfigureAwait(true);
        using var missingBody = Json("{\"projectId\":\"missing\",\"content\":\"rejected\"}");
        using var missing = await alice.PostAsync(Route("/cowork/memory"), missingBody, token).ConfigureAwait(true);
        foreign.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        missing.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        (await foreign.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBe(await missing.Content.ReadAsStringAsync(token).ConfigureAwait(true));
    }

    private static async Task CheckRestartAndCascadeAsync(HttpClient alice, HttpClient bob, CancellationToken token)
    {
        (await alice.GetStringAsync(Route("/cowork/projects/p1"), token).ConfigureAwait(true)).ShouldContain("persisted");
        (await alice.GetStringAsync(Route("/cowork/instructions/global"), token).ConfigureAwait(true)).ShouldContain("remember this");
        (await alice.GetStringAsync(Route("/cowork/memory/settings"), token).ConfigureAwait(true)).ShouldContain("\"enabled\":true");
        var export = await alice.GetStringAsync(Route("/cowork/memory/export"), token).ConfigureAwait(true);
        export.ShouldContain("project note");
        export.ShouldContain("account note");
        export.ShouldNotContain("rejected");
        using var denied = await bob.GetAsync(Route("/cowork/projects/p1"), token).ConfigureAwait(true);
        denied.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        (await bob.GetStringAsync(Route("/cowork/projects"), token).ConfigureAwait(true)).ShouldNotContain("Alpha");
        (await bob.GetStringAsync(Route("/cowork/instructions/global"), token).ConfigureAwait(true)).ShouldNotContain("remember this");
        using var recallBody = Json("{\"projectId\":\"p1\",\"query\":\"project\",\"k\":5}");
        using var recalled = await alice.PostAsync(Route("/cowork/memory/recall"), recallBody, token).ConfigureAwait(true);
        recalled.StatusCode.ShouldBe(HttpStatusCode.OK);
        (await recalled.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldContain("project note");
        (await bob.GetStringAsync(Route("/cowork/memory/export"), token).ConfigureAwait(true)).ShouldNotContain("project note");
        using var deleted = await alice.DeleteAsync(Route("/cowork/projects/p1"), token).ConfigureAwait(true);
        deleted.StatusCode.ShouldBe(HttpStatusCode.NoContent);
        export = await alice.GetStringAsync(Route("/cowork/memory/export"), token).ConfigureAwait(true);
        export.ShouldNotContain("project note");
        export.ShouldContain("account note");
        (await bob.GetStringAsync(Route("/cowork/memory/export"), token).ConfigureAwait(true)).ShouldContain("bob note");
        using var noFolder = await alice.GetAsync(Route("/cowork/projects/folder"), token).ConfigureAwait(true);
        noFolder.StatusCode.ShouldBe(HttpStatusCode.NotFound);
    }

    [Fact]
    public async Task ConcurrentCreatesCannotExceedAccountCap()
    {
        var token = TestContext.Current.CancellationToken;
        var seed = _app!.CreateCommand("""
            INSERT INTO cowork_projects (id, account_id, name, created_at, updated_at)
            SELECT 'seed-' || n::text, 'alice', 'seed', now(), now() FROM generate_series(1, 199) AS n
            """);
        await using (seed.ConfigureAwait(true))
        {
            await seed.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        var firstHost = await StartAsync().ConfigureAwait(true);
        await using var firstHostAsyncDisposal = firstHost.ConfigureAwait(true);
        var secondHost = await StartAsync().ConfigureAwait(true);
        await using var secondHostAsyncDisposal = secondHost.ConfigureAwait(true);
        using var first = Client(firstHost, "alice");
        using var second = Client(secondHost, "alice");
        using var firstBody = Json("{\"id\":\"new1\",\"name\":\"One\"}");
        using var secondBody = Json("{\"id\":\"new2\",\"name\":\"Two\"}");
        var creates = await Task.WhenAll(
            first.PutAsync(Route("/cowork/projects/new1"), firstBody, token),
            second.PutAsync(Route("/cowork/projects/new2"), secondBody, token)).ConfigureAwait(true);
        try
        {
            creates.Count(static response => response.StatusCode == HttpStatusCode.Created).ShouldBe(1);
            creates.Count(static response => response.StatusCode == HttpStatusCode.BadRequest).ShouldBe(1);
        }
        finally
        {
            foreach (var response in creates) response.Dispose();
        }
        var count = _app.CreateCommand("SELECT count(*) FROM cowork_projects WHERE account_id = 'alice'");
        await using var countAsyncDisposal = count.ConfigureAwait(true);
        ((long)(await count.ExecuteScalarAsync(token).ConfigureAwait(true))!).ShouldBe(200);
    }

    [Fact]
    public async Task ProductionRootRequiresAuthenticationAndHonorsDisabledModules()
    {
        var token = TestContext.Current.CancellationToken;
        var factory = await StartAsync(enabled: false).ConfigureAwait(true);
        await using var factoryAsyncDisposal = factory.ConfigureAwait(true);
        using var anonymous = factory.CreateClient();
        using var alice = Client(factory, "alice");
