        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task IndependentHostsSerializeSameKey(bool different)
    {
        var token = TestContext.Current.CancellationToken;
        var firstHost = await StartAsync(source: _app).ConfigureAwait(true);
        await using var firstHostAsyncDisposal = firstHost.ConfigureAwait(true);
        var secondHost = await StartAsync(source: _otherApp).ConfigureAwait(true);
        await using var secondHostAsyncDisposal = secondHost.ConfigureAwait(true);
        var gateConnection = await _app!.OpenConnectionAsync(token).ConfigureAwait(true);
        await using var gateConnectionAsyncDisposal = gateConnection.ConfigureAwait(true);
        var gate = new NpgsqlCommand("SELECT pg_advisory_lock(hashtextextended('cowork-memory:alice', 0))", gateConnection);
        await using var gateAsyncDisposal = gate.ConfigureAwait(true);
        await gate.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        var results = await FinishSameKeyRaceAsync(gateConnection, firstHost, secondHost, different, token).ConfigureAwait(true);
        using var firstResult = results[0];
        using var secondResult = results[1];
        results.Count(static r => r.StatusCode == HttpStatusCode.Created).ShouldBe(different ? 1 : 2);
        if (different)
        {
            results.Count(static r => r.StatusCode == HttpStatusCode.Conflict).ShouldBe(1);
        }
        else
        {
            firstResult.Content.Headers.ContentType?.ToString().ShouldBe(secondResult.Content.Headers.ContentType?.ToString());
            (await firstResult.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBe(await secondResult.Content.ReadAsStringAsync(token).ConfigureAwait(true));
        }

        await AssertCountsAsync(1, 1, token).ConfigureAwait(true);
    }

    private async Task<HttpResponseMessage[]> FinishSameKeyRaceAsync(
        NpgsqlConnection gateConnection, ApiFactory firstHost, ApiFactory secondHost, bool different, CancellationToken token)
    {
        var firstRunner = new RequestRunner(firstHost);
        var secondRunner = new RequestRunner(secondHost);
        var one = firstRunner.SendAsync("race", "{\"content\":\"one\",\"topic\":\"t\"}", token);
        var two = secondRunner.SendAsync("race", different ? "{\"content\":\"two\",\"topic\":\"t\"}" : "{\"topic\":\"t\",\"unknown\":42,\"content\":\"one\"}", token);
        HttpResponseMessage[] results;
        try
        {
            await WaitForBlockedAsync("SELECT pg_advisory_xact_lock", 2, token).ConfigureAwait(true);
        }
        finally
        {
            var release = new NpgsqlCommand("SELECT pg_advisory_unlock(hashtextextended('cowork-memory:alice', 0))", gateConnection);
            await using var releaseAsyncDisposal = release.ConfigureAwait(true);
            await release.ExecuteNonQueryAsync(CancellationToken.None).ConfigureAwait(true);
            results = await Task.WhenAll(one, two).ConfigureAwait(true);
        }
        return results;
    }

    [Fact]
    public async Task RestartReplayValidationIsolationAndErasure()
    {
        var token = TestContext.Current.CancellationToken;
        const string body = "{\"content\":\"private note\"}";
        var saved = await SeedRestartReplayAsync(body, token).ConfigureAwait(true);

        var restarted = await StartAsync(source: _otherApp).ConfigureAwait(true);
        await using var restartedAsyncDisposal = restarted.ConfigureAwait(true);
        using var client = Client(restarted, "alice");
        using var replay = await SendKeyedAsync(client, "restart", body, token).ConfigureAwait(true);
        replay.StatusCode.ShouldBe(HttpStatusCode.Created);
        replay.Content.Headers.ContentType?.MediaType.ShouldBe("application/json");
        (await replay.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBe(saved);
        using var document = JsonDocument.Parse(saved);
        var id = document.RootElement.GetProperty("id").GetString();
        using var deleted = await client.DeleteAsync(Route("/cowork/memory/" + id), token).ConfigureAwait(true);
        deleted.StatusCode.ShouldBe(HttpStatusCode.NoContent);
        using var gone = await SendKeyedAsync(client, "restart", body, token).ConfigureAwait(true);
        gone.StatusCode.ShouldBe(HttpStatusCode.Gone);
        (await gone.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBeEmpty();
        using var conflict = await SendKeyedAsync(client, "restart", "{\"content\":\"changed\"}", token).ConfigureAwait(true);
        conflict.StatusCode.ShouldBe(HttpStatusCode.Conflict);
        await AssertCountsAsync(1, 2, token).ConfigureAwait(true);
    }

    private async Task<string> SeedRestartReplayAsync(string body, CancellationToken token)
    {
        var firstHost = await StartAsync(source: _app).ConfigureAwait(true);
        await using var firstHostAsyncDisposal = firstHost.ConfigureAwait(true);
        var secondHost = await StartAsync(source: _otherApp).ConfigureAwait(true);
        await using var secondHostAsyncDisposal = secondHost.ConfigureAwait(true);
        using var alice = Client(firstHost, "alice");
        using var bob = Client(secondHost, "bob");
        using var created = await SendKeyedAsync(alice, "restart", body, token).ConfigureAwait(true);
        created.StatusCode.ShouldBe(HttpStatusCode.Created);
        var saved = await created.Content.ReadAsStringAsync(token).ConfigureAwait(true);
        using var invalid = await SendKeyedAsync(alice, "restart", "{\"content\":", token).ConfigureAwait(true);
        invalid.StatusCode.ShouldBe(HttpStatusCode.BadRequest);
        using var missingContent = await SendKeyedAsync(alice, "restart", "{}", token).ConfigureAwait(true);
        missingContent.StatusCode.ShouldBe(HttpStatusCode.BadRequest);
        using var foreign = await SendKeyedAsync(bob, "restart", "{\"content\":\"bob note\"}", token).ConfigureAwait(true);
        foreign.StatusCode.ShouldBe(HttpStatusCode.Created);
        (await foreign.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldNotContain("private note");
        return saved;
    }

    [Fact]
    public async Task ResetAndProjectCascadeLeaveNonDisclosingClaims()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync().ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var alice = Client(host, "alice");
        using var bob = Client(host, "bob");
        using var projectRequestBody = Json("{\"id\":\"own\",\"name\":\"Own\"}");
        using var project = await alice.PutAsync(Route("/cowork/projects/own"), projectRequestBody, token).ConfigureAwait(true);
        using var foreignProjectBody = Json("{\"id\":\"foreign\",\"name\":\"Foreign\"}");
        using var foreignProject = await bob.PutAsync(Route("/cowork/projects/foreign"), foreignProjectBody, token).ConfigureAwait(true);
        project.StatusCode.ShouldBe(HttpStatusCode.Created);
        foreignProject.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var foreign = await SendKeyedAsync(alice, "foreign", "{\"projectId\":\"foreign\",\"content\":\"x\"}", token).ConfigureAwait(true);
        using var missing = await SendKeyedAsync(alice, "missing", "{\"projectId\":\"missing\",\"content\":\"x\"}", token).ConfigureAwait(true);
        foreign.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        missing.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        (await foreign.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBe(await missing.Content.ReadAsStringAsync(token).ConfigureAwait(true));
        const string projectBody = "{\"projectId\":\"own\",\"content\":\"project secret\"}";
        using var saved = await SendKeyedAsync(alice, "project", projectBody, token).ConfigureAwait(true);
        saved.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var delete = await alice.DeleteAsync(Route("/cowork/projects/own"), token).ConfigureAwait(true);
        delete.StatusCode.ShouldBe(HttpStatusCode.NoContent);
        using var gone = await SendKeyedAsync(alice, "project", projectBody, token).ConfigureAwait(true);
        gone.StatusCode.ShouldBe(HttpStatusCode.Gone);
        using var account = await SendKeyedAsync(alice, "reset", "{\"content\":\"reset secret\"}", token).ConfigureAwait(true);
        account.StatusCode.ShouldBe(HttpStatusCode.Created);
        using var resetBody = Json("{}");
        using var reset = await alice.PostAsync(Route("/cowork/memory/reset"), resetBody, token).ConfigureAwait(true);
        reset.StatusCode.ShouldBe(HttpStatusCode.NoContent);
        using var resetReplay = await SendKeyedAsync(alice, "reset", "{\"content\":\"reset secret\"}", token).ConfigureAwait(true);
        resetReplay.StatusCode.ShouldBe(HttpStatusCode.Gone);
        await AssertCountsAsync(0, 2, token).ConfigureAwait(true);
    }

    [Fact]
    public async Task FailureBeforeCommitRollsBackAndRetryCreates()
    {
        var token = TestContext.Current.CancellationToken;
        var setup = _admin!.CreateCommand($"""
            CREATE FUNCTION "{_schema}".reject_claim() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN RAISE EXCEPTION 'injected claim failure'; END $$;
            CREATE TRIGGER reject_claim BEFORE INSERT ON "{_schema}".cowork_memory_idempotency
            FOR EACH ROW EXECUTE FUNCTION "{_schema}".reject_claim()
            """);
        await using (setup.ConfigureAwait(true))
        {
            await setup.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        var host = await StartAsync().ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var client = Client(host, "alice");
        using var failed = await SendKeyedAsync(client, "failure", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        failed.StatusCode.ShouldBe(HttpStatusCode.ServiceUnavailable);
        await AssertCountsAsync(0, 0, token).ConfigureAwait(true);
        var drop = _admin.CreateCommand($"DROP TRIGGER reject_claim ON \"{_schema}\".cowork_memory_idempotency");
        await using (drop.ConfigureAwait(true))
        {
            await drop.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        using var retry = await SendKeyedAsync(client, "failure", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        retry.StatusCode.ShouldBe(HttpStatusCode.Created);
        await AssertCountsAsync(1, 1, token).ConfigureAwait(true);
    }

    [Fact]
    public async Task ProjectDeleteWinsBeforeKeyedSave()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync().ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var client = Client(host, "alice");
        using var createdBody = Json("{\"id\":\"race\",\"name\":\"Race\"}");
        using var created = await client.PutAsync(Route("/cowork/projects/race"), createdBody, token).ConfigureAwait(true);
        created.StatusCode.ShouldBe(HttpStatusCode.Created);
        var connection = await _app!.OpenConnectionAsync(token).ConfigureAwait(true);
        await using var connectionAsyncDisposal = connection.ConfigureAwait(true);
        var transaction = await connection.BeginTransactionAsync(token).ConfigureAwait(true);
        await using var transactionAsyncDisposal = transaction.ConfigureAwait(true);
        var delete = new NpgsqlCommand("DELETE FROM cowork_projects WHERE id = 'race' AND account_id = 'alice'", connection, transaction);
        await using var deleteAsyncDisposal = delete.ConfigureAwait(true);
        await delete.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        var save = new RequestRunner(host).SendAsync("race", "{\"projectId\":\"race\",\"content\":\"note\"}", token);
        HttpResponseMessage result;
        try
        {
            await WaitForBlockedAsync("SELECT 1 FROM cowork_projects", 1, token).ConfigureAwait(true);
            await transaction.CommitAsync(token).ConfigureAwait(true);
        }
        finally
        {
            await transaction.DisposeAsync().ConfigureAwait(true);
            result = await save.ConfigureAwait(true);
        }
        using var resultDisposal = result;
        result.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        await AssertCountsAsync(0, 0, token).ConfigureAwait(true);
    }

    [Fact]
    public async Task KeyedSaveWinsBeforeProjectDelete()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync().ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var client = Client(host, "alice");
        using var createdBody = Json("{\"id\":\"race\",\"name\":\"Race\"}");
        using var created = await client.PutAsync(Route("/cowork/projects/race"), createdBody, token).ConfigureAwait(true);
        created.StatusCode.ShouldBe(HttpStatusCode.Created);
        var setup = _admin!.CreateCommand($"""
            CREATE FUNCTION "{_schema}".block_memory_insert() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(TG_TABLE_SCHEMA, 0)); RETURN NEW; END $$;
            CREATE TRIGGER block_memory_insert BEFORE INSERT ON "{_schema}".cowork_memory_entries
            FOR EACH ROW EXECUTE FUNCTION "{_schema}".block_memory_insert()
            """);
        await using (setup.ConfigureAwait(true))
        {
            await setup.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        var connection = await _app!.OpenConnectionAsync(token).ConfigureAwait(true);
        await using var connectionAsyncDisposal = connection.ConfigureAwait(true);
        var gate = new NpgsqlCommand("SELECT pg_advisory_lock(hashtextextended(@schema, 0))", connection);
        await using var gateAsyncDisposal = gate.ConfigureAwait(true);
        gate.Parameters.AddWithValue("schema", _schema);
        await gate.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        const string body = "{\"projectId\":\"race\",\"content\":\"note\"}";
        var runner = new RequestRunner(host);
        var (saved, deleted) = await FinishSaveBeforeDeleteAsync(connection, runner, body, token).ConfigureAwait(true);
        using var savedDisposal = saved;
        using var deletedDisposal = deleted;
        deleted.ShouldNotBeNull();
        saved.StatusCode.ShouldBe(HttpStatusCode.Created);
        deleted.StatusCode.ShouldBe(HttpStatusCode.NoContent);
        using var replay = await SendKeyedAsync(client, "race", body, token).ConfigureAwait(true);
        replay.StatusCode.ShouldBe(HttpStatusCode.Gone);
        await AssertCountsAsync(0, 1, token).ConfigureAwait(true);
    }

    private async Task<(HttpResponseMessage Saved, HttpResponseMessage? Deleted)> FinishSaveBeforeDeleteAsync(
        NpgsqlConnection connection, RequestRunner runner, string body, CancellationToken token)
    {
        var save = runner.SendAsync("race", body, token);
        Task<HttpResponseMessage>? delete = null;
        HttpResponseMessage saved;
        HttpResponseMessage? deleted;
        try
        {
            await WaitForBlockedAsync("INSERT INTO cowork_memory_entries", 1, token).ConfigureAwait(true);
            delete = runner.DeleteAsync("/cowork/projects/race", token);
            await WaitForBlockedAsync("DELETE FROM cowork_projects", 1, token).ConfigureAwait(true);
        }
        finally
        {
            var release = new NpgsqlCommand("SELECT pg_advisory_unlock(hashtextextended(@schema, 0))", connection);
            await using var releaseAsyncDisposal = release.ConfigureAwait(true);
            release.Parameters.AddWithValue("schema", _schema);
            await release.ExecuteNonQueryAsync(CancellationToken.None).ConfigureAwait(true);
            saved = await save.ConfigureAwait(true);
            deleted = delete is null ? null : await delete.ConfigureAwait(true);
        }
        return (saved, deleted);
    }

    [Fact]
    public async Task DatabaseFailureDoesNotFallBackToLocalMemory()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync().ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var client = Client(host, "alice");
        using var first = await SendKeyedAsync(client, "outage", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        first.StatusCode.ShouldBe(HttpStatusCode.Created);
        var revoke = _admin!.CreateCommand($"REVOKE SELECT ON \"{_schema}\".cowork_memory_idempotency FROM \"{_role}\"");
        await using (revoke.ConfigureAwait(true))
        {
            await revoke.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        using var unavailable = await SendKeyedAsync(client, "outage", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        unavailable.StatusCode.ShouldBe(HttpStatusCode.ServiceUnavailable);
        var grant = _admin.CreateCommand($"GRANT SELECT ON \"{_schema}\".cowork_memory_idempotency TO \"{_role}\"");
        await using (grant.ConfigureAwait(true))
        {
            await grant.ExecuteNonQueryAsync(token).ConfigureAwait(true);
        }
        using var replay = await SendKeyedAsync(client, "outage", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        replay.StatusCode.ShouldBe(HttpStatusCode.Created);
        (await replay.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldBe(await first.Content.ReadAsStringAsync(token).ConfigureAwait(true));
        await AssertCountsAsync(1, 1, token).ConfigureAwait(true);
    }

    [Fact]
    public async Task LostHttpAcknowledgementReplaysCommittedResult()
    {
        var token = TestContext.Current.CancellationToken;
        var adapter = new SuppressAcknowledgementStore(new PostgresMemoryStore(_app!));
        var firstHost = await StartAsync(source: _app, memory: adapter).ConfigureAwait(true);
        await using var firstHostAsyncDisposal = firstHost.ConfigureAwait(true);
        var secondHost = await StartAsync(source: _otherApp).ConfigureAwait(true);
        await using var secondHostAsyncDisposal = secondHost.ConfigureAwait(true);
        using var first = Client(firstHost, "alice");
        using var second = Client(secondHost, "alice");
        using var lost = await SendKeyedAsync(first, "lost", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        lost.StatusCode.ShouldBe(HttpStatusCode.ServiceUnavailable);
        await AssertCountsAsync(1, 1, token).ConfigureAwait(true);
        using var replay = await SendKeyedAsync(second, "lost", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        replay.StatusCode.ShouldBe(HttpStatusCode.Created);
        (await replay.Content.ReadAsStringAsync(token).ConfigureAwait(true)).ShouldContain("once");
        await AssertCountsAsync(1, 1, token).ConfigureAwait(true);
    }

    [Fact]
    public async Task MissingDurableCapabilityFailsClosed()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync(memory: new ForwardingStore(new InMemoryMemoryStore())).ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
        using var client = Client(host, "alice");
        using var keyed = await SendKeyedAsync(client, "unavailable", "{\"content\":\"once\"}", token).ConfigureAwait(true);
        keyed.StatusCode.ShouldBe(HttpStatusCode.ServiceUnavailable);
        using var unkeyedBody = Json("{\"content\":\"normal\"}");
        using var unkeyed = await client.PostAsync(Route("/cowork/memory"), unkeyedBody, token).ConfigureAwait(true);
        unkeyed.StatusCode.ShouldBe(HttpStatusCode.Created);
    }

