    public async Task ProductionInMemoryStoreCannotAdvertiseDurability()
    {
        var token = TestContext.Current.CancellationToken;
        var host = await StartAsync(memory: new InMemoryMemoryStore()).ConfigureAwait(true);
        await using var hostAsyncDisposal = host.ConfigureAwait(true);
