    private class ForwardingStore(IMemoryStore inner) : IMemoryStore
    {
        public Task<MemorySettings> GetSettingsAsync(string accountId, CancellationToken cancellationToken) => inner.GetSettingsAsync(accountId, cancellationToken);
        public Task SetSettingsAsync(string accountId, MemorySettings settings, CancellationToken cancellationToken) => inner.SetSettingsAsync(accountId, settings, cancellationToken);
        public Task<MemoryMutation> SaveAsync(MemoryScope scope, MemoryDraft draft, CancellationToken cancellationToken) => inner.SaveAsync(scope, draft, cancellationToken);
        public Task<MemoryRecall> RecallAsync(MemoryScope scope, string? query, int k, CancellationToken cancellationToken) => inner.RecallAsync(scope, query, k, cancellationToken);
        public Task<MemoryMutation> DeleteAsync(MemoryScope scope, string id, CancellationToken cancellationToken) => inner.DeleteAsync(scope, id, cancellationToken);
        public Task<MemoryMutation> ResetAsync(string accountId, CancellationToken cancellationToken) => inner.ResetAsync(accountId, cancellationToken);
        public Task<MemoryExport> ExportAsync(string accountId, CancellationToken cancellationToken) => inner.ExportAsync(accountId, cancellationToken);
    }

    // Simulates loss between a committed store result and the HTTP response, not process termination.
    private sealed class SuppressAcknowledgementStore(PostgresMemoryStore inner) : ForwardingStore(inner), IMemoryIdempotentStore
    {
        public async Task<MemoryIdempotentResult> SaveIdempotentAsync(MemoryScope scope, MemoryDraft draft, string key, CancellationToken cancellationToken)
        {
            var result = await inner.SaveIdempotentAsync(scope, draft, key, cancellationToken).ConfigureAwait(true);
            return result.Status == MemoryIdempotentStatus.Created ? new(MemoryIdempotentStatus.Unavailable, null) : result;
        }
    }

    private async Task WaitForBlockedAsync(string sql, int minimum, CancellationToken token)
    {
        for (var attempt = 0; attempt < 200; attempt++)
        {
            var command = _admin!.CreateCommand("SELECT count(*) FROM pg_stat_activity WHERE application_name = @app AND wait_event_type = 'Lock' AND position(@sql in query) > 0");
            await using var commandAsyncDisposal = command.ConfigureAwait(true);
            command.Parameters.AddWithValue("app", _schema);
            command.Parameters.AddWithValue("sql", sql);
            if ((long)(await command.ExecuteScalarAsync(token).ConfigureAwait(true))! >= minimum) return;
            await Task.Delay(25, token).ConfigureAwait(true);
        }
        throw new TimeoutException("The expected database lock wait was not observed.");
    }

    private async Task AssertCountsAsync(long entries, long claims, CancellationToken token)
    {
        var command = _app!.CreateCommand("SELECT (SELECT count(*) FROM cowork_memory_entries), (SELECT count(*) FROM cowork_memory_idempotency)");
        await using var commandAsyncDisposal = command.ConfigureAwait(true);
        var reader = await command.ExecuteReaderAsync(token).ConfigureAwait(true);
        await using var readerAsyncDisposal = reader.ConfigureAwait(true);
        (await reader.ReadAsync(token).ConfigureAwait(true)).ShouldBeTrue();
        (await reader.GetFieldValueAsync<long>(0, token).ConfigureAwait(true)).ShouldBe(entries);
        (await reader.GetFieldValueAsync<long>(1, token).ConfigureAwait(true)).ShouldBe(claims);
    }

    private sealed class RequestRunner(ApiFactory host)
    {
        public async Task<HttpResponseMessage> SendAsync(string key, string body, CancellationToken token)
        {
            using var client = Client(host, "alice");
            return await SendKeyedAsync(client, key, body, token).ConfigureAwait(true);
        }

        public async Task<HttpResponseMessage> DeleteAsync(string path, CancellationToken token)
        {
            using var client = Client(host, "alice");
            return await client.DeleteAsync(Route(path), token).ConfigureAwait(true);
        }
    }

    private static async Task<HttpResponseMessage> SendKeyedAsync(HttpClient client, string key, string body, CancellationToken token)
    {
        using var request = new HttpRequestMessage(HttpMethod.Post, "/cowork/memory") { Content = Json(body) };
        request.Headers.TryAddWithoutValidation("Idempotency-Key", key);
        return await client.SendAsync(request, token).ConfigureAwait(true);
    }

    private Task<ApiFactory> StartAsync(bool enabled = true, NpgsqlDataSource? source = null, IMemoryStore? memory = null)
    {
        source ??= _app!;
        var settings = JwtTestHost.ProductionConfig();
        settings["Sessions:Postgres:ConnectionString"] = source.ConnectionString;
        settings["Cowork:Projects:Enabled"] = enabled ? "true" : "false";
        settings["Cowork:Memory:Enabled"] = enabled ? "true" : "false";
        return Task.FromResult(new ApiFactory(settings, services =>
        {
            services.AddSingleton(source);
            services.RemoveAll<IMemoryStore>();
            services.AddSingleton<IMemoryStore>(memory ?? new PostgresMemoryStore(source));
            JwtTestHost.InjectStaticMetadata(services);
        }, environment: "Production"));
    }

    private static HttpClient Client(ApiFactory app, string subject)
    {
        var client = app.CreateClient();
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", JwtTestHost.IssueToken(subject));
        return client;
    }

    private static StringContent Json(string value) => new(value, Encoding.UTF8, "application/json");

    private static Uri Route(string path) => new(path, UriKind.Relative);
}
